insert into public.sops select * from json_populate_recordset(null::public.sops, '[{"id":"3797aa87-5713-4f0d-adc6-dd6d00fe6658","master_plan_id":"73a766ff-9c10-4bb6-bd98-ff2a2a461267","title":"New Client Onboarding","pillar_key":"onboarding","purpose":"Give every new client the same warm, organized start, so they feel taken care of from the first day and nothing gets missed.","steps":["Send the welcome email with the signed agreement and first invoice within one business day", "Add the client to Contacts with the Client relationship and their package tag", "Send the Brand Clarity questionnaire and ask for it back within 5 days", "Create their project folder and share it with them", "Book the 60-minute kickoff call from the Brand Discovery calendar", "After the kickoff, send a recap with the three next steps and their due dates", "Add a 30-day check-in task so the first month never passes in silence"],"owner":"Eloise Marchand","tools":"Contacts, Calendars, Campaigns & Broadcasts","status":"active","last_reviewed":"2026-09-15","created_at":"2026-10-02T18:20:27.715503+00:00","updated_at":"2026-10-02T18:20:27.715503+00:00"}, 
 {"id":"a08e00d0-c91b-4d39-bed0-005caf49bb75","master_plan_id":"73a766ff-9c10-4bb6-bd98-ff2a2a461267","title":"Discovery Call to Proposal","pillar_key":"sales-journey","purpose":"Turn a good discovery call into a clear proposal within 48 hours, while the conversation is still fresh for both of you.","steps":["Before the call, read their Brand Clarity Quiz answers and their contact timeline", "On the call, ask the five discovery questions and write down their own words", "Move their card to Proposal in the Pipeline and enter the deal value", "Draft the proposal from the matching package in Offers & Packages", "Send the proposal within 48 hours with a booking link for a 20-minute review call", "Schedule a follow-up on their contact record for three days later", "Mark the deal Won or Lost with a one-line reason, so the pattern shows up in the Weekly Review"],"owner":"Eloise Marchand","tools":"Pipeline, Offers & Packages, Contacts","status":"active","last_reviewed":"2026-09-22","created_at":"2026-10-02T18:20:27.715503+00:00","updated_at":"2026-10-02T18:20:27.715503+00:00"}, 
 {"id":"06375230-2ed8-4d5b-adb9-91c705a2033f","master_plan_id":"73a766ff-9c10-4bb6-bd98-ff2a2a461267","title":"Monthly Newsletter","pillar_key":"communication","purpose":"Send one useful, on-brand newsletter on the first Tuesday of every month, without it becoming a last-minute scramble.","steps":["By the 20th, pick the theme from this month''s Marketing Plan", "Write the main story (300 to 400 words) and one client spotlight", "Choose one offer or event to feature, with a single button", "Build it as a Broadcast to everyone tagged newsletter", "Send a test to yourself and read it on your phone", "Schedule it for the first Tuesday at 9am", "A week later, note opens and replies in the Weekly Review"],"owner":"Grace Okafor","tools":"Campaigns & Broadcasts, Marketing Plan","status":"draft","last_reviewed":null,"created_at":"2026-10-02T18:20:27.715503+00:00","updated_at":"2026-10-02T18:20:27.715503+00:00"}]'::json) on conflict do nothing;
